const quietRender=render;let lastWaitingView='';render=function(){const waiting=!facilitatorMode&&state.waitingPhase&&document.querySelector('.waiting-state');if(waiting){const signature=`${state.phase}|${state.globalPhase}|${state.waitingPhase}|${JSON.stringify(state.releasedEvidence)}`;if(signature===lastWaitingView){updateTimer();return}lastWaitingView=signature}quietRender()};
const stageMinutes=[8,10,8,10,8,8,8];let stageTimerPhase=0,stageTimerStartedAt=0;const stageTimerKey='it235-phaseStartedAt';function updateStageTimer(){const el=document.querySelector('#timerDisplay');if(!el)return;if(!state.started){stageTimerPhase=0;stageTimerStartedAt=0;localStorage.removeItem(stageTimerKey);el.textContent='08:00';el.classList.remove('urgent');return}if(stageTimerPhase!==state.phase||!stageTimerStartedAt){stageTimerPhase=state.phase;stageTimerStartedAt=Number(localStorage.getItem(stageTimerKey)||0);if(!stageTimerStartedAt){stageTimerStartedAt=Date.now();localStorage.setItem(stageTimerKey,String(stageTimerStartedAt))}}const remaining=Math.max(0,stageMinutes[state.phase-1]*60*1000-(Date.now()-stageTimerStartedAt));el.textContent=`${String(Math.floor(remaining/60000)).padStart(2,'0')}:${String(Math.floor((remaining%60000)/1000)).padStart(2,'0')}`;el.classList.toggle('urgent',remaining<2*60*1000)}updateTimer=updateStageTimer;setInterval(updateStageTimer,1000);updateStageTimer();document.addEventListener('click',e=>{if(!e.target.closest('.waiting-orbit')||!state.started||!state.waitingPhase||state.phase>=7)return;state.phase+=1;state.globalPhase=state.phase;state.waitingPhase=0;localStorage.removeItem('it235-waitingPhase');localStorage.removeItem(stageTimerKey);localStorage.setItem('it235-phase',String(state.phase));showToast(`Test advance: ${phases[state.phase-1]}`);render()});
let observedStage=state.phase;setInterval(()=>{if(state.started&&state.phase!==observedStage){observedStage=state.phase;stageTimerPhase=state.phase;stageTimerStartedAt=Date.now();localStorage.setItem(stageTimerKey,String(stageTimerStartedAt));updateStageTimer()}},250);
const sourceDetails={'user-interview':'One customer service employee cannot load the portal from the office network. They can reach email and the public status page. A coworker in another department reports the same portal symptom.','service-desk':'Tickets come from Customer Service, Finance, and one remote employee. All mention portal timeouts. One ticket says, “the entire network is down,” but the user also confirms email is working.','monitoring':'The portal health check is green from the monitoring location, but transaction latency is elevated. Authentication, email, and the status page are healthy.','recent-change':'A configuration change affecting a shared gateway was completed at 8:31 AM. The change passed a limited check from one location. It is a credible lead, not proof of cause.','logs':'Requests from several networks reach the gateway but fail during a dependency call. The error pattern began after the configuration change and is absent from unaffected services.','verification':'The portal loads for a test account from the office network, but a customer simulation still fails from a second network. The change is not yet verified for all affected users.'};document.addEventListener('click',e=>{const req=e.target.closest('[data-request]');if(!req)return;e.preventDefault();e.stopImmediatePropagation();saveFields();const id=req.dataset.request;state.answers.requestEvidence=id;localStorage.setItem('it235-answers',JSON.stringify(state.answers));document.querySelectorAll('.request-option').forEach(x=>x.classList.toggle('selected',x.dataset.request===id));let result=document.querySelector('#sourceResult');if(!result){result=document.createElement('div');result.id='sourceResult';document.querySelector('#requestForm')?.before(result)}result.innerHTML=`<div class="source-result"><div class="phase-kicker">Source returned · ${req.querySelector('b')?.textContent||id}</div><p>${sourceDetails[id]||'No source information is available yet.'}</p><label for="learn-${id}">What did we learn from this source?</label><textarea id="learn-${id}" data-learning placeholder="Record the fact or uncertainty this source added to your investigation.">${state.answers[`learn-${id}`]||''}</textarea></div>`});
document.addEventListener('click',e=>{const req=e.target.closest('[data-request]');if(!req)return;e.preventDefault();e.stopImmediatePropagation();saveFields();const id=req.dataset.request;state.answers.requestEvidence=id;localStorage.setItem('it235-answers',JSON.stringify(state.answers));document.querySelectorAll('.request-option').forEach(x=>x.classList.toggle('selected',x.dataset.request===id));let result=document.querySelector('#sourceResult');if(!result){result=document.createElement('div');result.id='sourceResult';document.querySelector('#requestForm')?.before(result)}result.innerHTML=`<div class="source-result"><div class="phase-kicker">Source returned · ${req.querySelector('b')?.textContent||id}</div><p>${sourceDetails[id]||'No source information is available yet.'}</p><label for="learn-${id}">What did we learn from this source?</label><textarea id="learn-${id}" data-learning placeholder="Record the fact or uncertainty this source added to your investigation.">${state.answers[`learn-${id}`]||''}</textarea></div>`},true);
Object.assign(sourceDetails,{'user-interview':'09:02 — A Customer Service employee reports that the portal login page loads, but submitting a customer search times out after about 30 seconds. Email, the public status page, and a separate internal tool work normally. A Finance employee reports the same customer-search symptom from a different office network. Neither person can say whether other portal functions are affected.','service-desk':'09:05 — Twelve tickets are open: seven from Customer Service, three from Finance, and two from a remote employee. Most mention portal timeouts beginning between 08:40 and 08:50. One ticket says “the entire network is down,” but its attached test confirms email works. No ticket reports a password or account-lockout error. The ticket system groups reports by department, not by network path.','monitoring':'The synthetic portal check is green because it reaches the landing page from one monitoring location. A deeper transaction check shows latency rising from 420 ms to 8.7 seconds before timing out. Authentication, email, and the public status page remain within normal ranges. The monitoring view does not currently break results down by user network or department.','recent-change':'08:31 — A change to the shared gateway configuration completed successfully according to the change record. The validation step checked a landing-page request from the primary office network only. The record shows a new routing rule and a dependency target change, but it does not establish that the change caused the incident. No comparable test was run from the remote network before closure.','logs':'2026-08-13 08:42:17 gateway INFO  request=7f31 route=portal source=office status=200 bytes=1842\n2026-08-13 08:42:18 portal  INFO  request=7f31 action=customer-search upstream=profile-check\n2026-08-13 08:42:18 gateway WARN  request=7f31 upstream=profile-check elapsed_ms=8120 retry=1\n2026-08-13 08:42:26 gateway ERROR request=7f31 upstream=profile-check error=upstream_timeout status=504\n2026-08-13 08:43:02 gateway ERROR request=80a4 upstream=profile-check error=upstream_timeout status=504 source=finance\n2026-08-13 08:44:11 status  INFO  request=91bc route=status-page source=office status=200\n2026-08-13 08:45:06 gateway WARN  request=a3d2 upstream=profile-check elapsed_ms=7904 retry=1 source=remote\n2026-08-13 08:45:14 gateway ERROR request=a3d2 upstream=profile-check error=upstream_timeout status=504 source=remote\n2026-08-13 08:46:30 auth    INFO  request=b7e8 action=login result=success source=office','verification':'After the first recovery attempt, a test account can load the portal and complete a search from the primary office network. A customer simulation from a second network still times out. The public status page and authentication remain healthy. The team has not yet confirmed whether the original business task works for representative users in every affected location.'});
Object.assign(sourceDetails,{'user-interview':'<span class="source-block"><b>Support:</b> “Northstar Service Desk, this is Maya. What are you seeing?”<br><b>Caller:</b> “The customer portal opens, but when I search for a customer it spins and then times out. I can still use email and the public status page.”<br><b>Support:</b> “Is anyone else seeing it?”<br><b>Caller:</b> “A Finance colleague just tried from another office and got the same result. My coworker can open the landing page, but we have not tested every portal task.”<br><b>Support:</b> “Are you seeing an error message?”<br><b>Caller:</b> “No useful message—just the timeout. It started sometime after the morning login rush.”</span>','service-desk':'<span class="source-block"><span class="ticket-item"><b>INC-1042 · Customer Service · 08:44</b><br>Portal customer search times out after the page loads. Email works. Two agents affected.</span><span class="ticket-item"><b>INC-1047 · Finance · 08:47</b><br>Customer lookup spins for about 30 seconds, then fails. Public status page loads normally.</span><span class="ticket-item"><b>INC-1051 · Remote employee · 08:49</b><br>“The whole network is down.” Follow-up test: email works; portal landing page loads, customer search fails.</span><span class="ticket-item"><b>INC-1056 · Customer Service · 08:52</b><br>Issue began after a morning restart. No password or account-lockout message reported.</span><small>Tickets are grouped by department, so the list does not yet prove whether the common factor is the user, location, application, or network path.</small></span>','monitoring':'<span class="dashboard-grid"><span class="signal-card"><b>Portal landing page</b><strong class="state green">GREEN</strong><small>99.8% availability · synthetic check passes</small></span><span class="signal-card"><b>Customer search transaction</b><strong class="state yellow">DEGRADED</strong><small>8.7 s p95 · timeout rate 31%</small></span><span class="signal-card"><b>Authentication</b><strong class="state green">GREEN</strong><small>99.99% success · normal latency</small></span><span class="signal-card"><b>Public status page</b><strong class="state green">GREEN</strong><small>Normal response time</small></span><span class="signal-card"><b>Gateway dependency calls</b><strong class="state yellow">ELEVATED</strong><small>Retry volume rising from multiple source networks</small></span><span class="signal-card"><b>Monitoring coverage</b><strong class="state gray">LIMITED</strong><small>Deep transaction check runs from one location</small></span></span>','recent-change':'<span class="change-log"><span><b>08:18</b> Windows quality update approved for the maintenance window.</span><span><b>08:24</b> Patch package staged to the shared gateway pool.</span><span><b>08:31</b> Windows patch installation completed; restart recorded as successful.</span><span><b>08:34</b> Post-change check passed: login page loaded from the primary office network.</span><span><b>08:42</b> First portal customer-search timeout reported.</span><small>The timing is important, but the post-change check covered only a shallow path from one location. The change log is a lead to test, not a complete explanation by itself.</small></span>'});requestCatalog.splice(requestCatalog.findIndex(x=>x[0]==='verification'),1);render();
sourceDetails['recent-change']='<span class="change-log"><span><b>08:05</b> Browser certificate inventory completed on the application hosts.</span><span><b>08:12</b> Overnight backup verification reported no errors.</span><span><b>08:18</b> Windows quality update approved for the maintenance window.</span><span><b>08:24</b> Patch package staged to the shared gateway pool.</span><span><b>08:31</b> Windows patch installation completed; restart recorded as successful.</span><span><b>08:34</b> Standard post-maintenance check completed: login page loaded from the primary office network.</span><span><b>08:37</b> Service account permissions review completed with no changes recorded.</span><span><b>08:42</b> First portal customer-search timeout reported.</span><span><b>08:46</b> Routine endpoint inventory job completed.</span></span>';
document.addEventListener('click',e=>{if(e.target.closest('.waiting-orbit')&&state.started&&state.waitingPhase&&state.phase<7)localStorage.setItem('it235-testFloor',String(state.phase+1))},true);document.querySelector('#resetBtn').addEventListener('click',()=>localStorage.removeItem('it235-testFloor'));
screens[4]=()=>`<div class="phase-kicker">Screen 04 · New development</div><h2>The incident changes</h2><p class="subhead">A new infrastructure report arrives. Do not simply confirm your first theory—decide what this evidence changes, what it does not prove, and what you need to test next.</p><section class="evidence-release"><span class="phase-kicker">New development · 09:06</span><article><b>Infrastructure update</b><p>Two gateway hosts began reporting portal transaction failures after the Windows quality update and restart. A third gateway host, still waiting for maintenance, is handling the same request type without the timeout. The portal landing page remains healthy on every host.</p><p>Traffic is distributed across the hosts, so affected users do not fail every time. The update is now a serious lead, but the team has not yet isolated the exact request path or confirmed that rolling it back will restore the business task.</p></article></section>${state.releasedEvidence.length?`<section class="evidence-release"><span class="phase-kicker">Additional released evidence</span>${state.releasedEvidence.map(e=>`<article><b>${e.title}</b><p>${e.content}</p></article>`).join('')}</section>`:''}${board()}${field('developmentUpdate','How has your hypothesis changed?','What do you now believe, and what caused the change?')}${field('nextAction','What should you do next?','Choose a controlled test, investigation step, or action.')}${field('actionRisk','What is the risk of that choice?','What could make the situation worse, and how would you limit that risk?')}${submitBlock(4,'updating conclusions, risk awareness, and a controlled next action.')}`;
screens[4]=()=>`<div class="phase-kicker">Screen 04 · New development</div><h2>The incident changes</h2><p class="subhead">A new infrastructure report arrives. Reassess the evidence, state what you think the issue is, then explain what you would do about it.</p><section class="evidence-release"><span class="phase-kicker">New development · 09:06</span><article><b>Infrastructure update</b><p>Two gateway hosts began reporting portal transaction failures after the Windows quality update and restart. A third gateway host, still waiting for maintenance, is handling the same request type without the timeout. The portal landing page remains healthy on every host.</p><p>Traffic is distributed across the hosts, so affected users do not fail every time.</p></article></section>${state.releasedEvidence.length?`<section class="evidence-release"><span class="phase-kicker">Additional released evidence</span>${state.releasedEvidence.map(e=>`<article><b>${e.title}</b><p>${e.content}</p></article>`).join('')}</section>`:''}${board()}${field('issueDiagnosis','What do you think the issue is?','State your best current diagnosis as clearly and specifically as you can.')}${field('developmentUpdate','How has your hypothesis changed?','What evidence changed or strengthened your thinking?')}${field('nextAction','What would you do next?','Choose a controlled test, fix, rollback, or investigation step.')}${field('actionRisk','What is the risk of that choice?','What could make the situation worse, and how would you limit that risk?')}${submitBlock(4,'a clear diagnosis, evidence-based adaptation, a controlled response, and risk awareness.')}`;if(!facilitatorMode)render();
if(summaryMode){const summaryBase=renderSummary;renderSummary=function(){summaryBase();document.querySelectorAll('.summary-card').forEach((card,i)=>{const diagnosis=state.teams[i]?.latest?.answer?.issueDiagnosis;if(diagnosis){const el=document.createElement('div');el.className='summary-diagnosis';el.innerHTML=`<span>Team diagnosis</span><p>${diagnosis}</p>`;card.querySelector('.summary-hypothesis')?.before(el)}})};renderFacilitator=renderSummary;render()}
const instructorDrafts={scores:{},pin:''};function renderInstructor(){state.phase=state.globalPhase;const currentPin=document.querySelector('#facilitatorPin')?.value||sessionStorage.getItem('it235-facilitatorPin')||instructorDrafts.pin;instructorDrafts.pin=currentPin;document.querySelectorAll('[data-score-input]').forEach(x=>instructorDrafts.scores[x.dataset.scoreInput]=x.value);const teams=state.teams.slice().sort((a,b)=>Number(b.ready)-Number(a.ready)||String(a.teamName).localeCompare(String(b.teamName)));const ready=teams.filter(t=>t.ready&&Number(t.phase)===state.globalPhase).length;const teamCards=teams.map(t=>{const latest=t.latest||{};const answer=latest.answer||{};const diagnosis=answer.issueDiagnosis||answer.developmentUpdate||answer.investigationDecision||'No current diagnosis submitted';const submitted=Boolean(t.ready&&Number(t.phase)===state.globalPhase);return `<article class="instructor-team ${submitted?'is-ready':''}"><div class="instructor-team-head"><div><span class="phase-kicker">${submitted?'Ready for review':t.ready?'Submitted earlier':'Working'}</span><h3>${t.teamName}</h3><small>${t.members}</small></div><div class="instructor-score"><strong>${t.score||0}</strong><span>pts</span></div></div><div class="instructor-status"><span class="status-pill">${submitted?'READY':'WAITING'}</span><span>Team phase ${t.phase||1}</span><span>${latest.kind||'No submission'}</span></div><div class="instructor-diagnosis"><span>Discussion lead</span><p>${diagnosis}</p></div><div class="instructor-board"><span><b>Know</b>${t.board?.known||'—'}</span><span><b>Think</b>${t.board?.think||'—'}</span><span><b>Unknown</b>${t.board?.unknown||'—'}</span></div><div class="score-entry"><input type="number" min="0" max="10" value="${instructorDrafts.scores[t.teamId]||''}" data-score-input="${t.teamId}" aria-label="Process points for ${t.teamName}" placeholder="0"><button class="primary-btn" data-score-team="${t.teamId}">Save points</button></div></article>`}).join('');const requests=state.requests.map(r=>`<article class="request-row"><div><b>${r.teamName} · ${r.evidenceId}</b><p>${r.question||r.reason}</p><small>${r.reason}</small></div><button class="primary-btn" data-release-evidence="${r.evidenceId}">${r.status==='released'?'Released':'Release evidence'}</button></article>`).join('');content.innerHTML=`<div class="instructor-head"><div><div class="phase-kicker">Instructor control room</div><h2>${state.incident?.name||'Incident room'}</h2><p class="subhead">Advance the class together, watch who is ready, score the process, and use the discussion view when you want the teams’ reasoning on the projector.</p></div><a class="secondary-btn" href="?mode=facilitator&view=summary">Open projector summary</a></div><section class="instructor-metrics"><div><span>Shared phase</span><strong>${state.globalPhase}</strong><small>${phases[state.globalPhase-1]}</small></div><div><span>Ready this phase</span><strong>${ready}/${teams.length}</strong><small>Teams submitted for review</small></div><div><span>Evidence requests</span><strong>${state.requests.length}</strong><small>Awaiting instructor action</small></div><div><span>Stage timer</span><strong id="instructorTimer">${document.querySelector('#timerDisplay')?.textContent||'--:--'}</strong><small>Time remaining</small></div></section><section class="review-card instructor-controls"><div class="instructor-controls-head"><div><span class="phase-kicker">Advance together</span><h3>Release the next screen when discussion is complete</h3></div><span class="status-pill">Phase ${state.globalPhase}</span></div><label for="facilitatorPin">Facilitator PIN</label><input id="facilitatorPin" type="password" value="${currentPin}" placeholder="Enter facilitator PIN"><div class="console-buttons">${phases.map((x,i)=>`<button class="primary-btn ${i+1===state.globalPhase?'current-control':''} ${i+1===state.globalPhase+1?'next-control':''}" data-release-phase="${i+1}">${i+1===state.globalPhase?'Current: ':i+1===state.globalPhase+1?'Next: ':'Release '}${i+1} · ${x}</button>`).join('')}</div></section><section class="review-card"><div class="instructor-controls-head"><div><span class="phase-kicker">Evidence queue</span><h3>Requests to discuss or release</h3></div></div>${requests||'<p class="summary-empty">No evidence requests yet.</p>'}</section><section class="instructor-team-grid">${teamCards||'<div class="review-card summary-empty">Teams appear after registration.</div>'}</section>`;updateStageTimer();const timer=document.querySelector('#instructorTimer');if(timer)timer.textContent=document.querySelector('#timerDisplay')?.textContent||'--:--'}
document.addEventListener('input',e=>{if(e.target.id==='facilitatorPin'){instructorDrafts.pin=e.target.value;sessionStorage.setItem('it235-facilitatorPin',e.target.value)}if(e.target.matches('[data-score-input]'))instructorDrafts.scores[e.target.dataset.scoreInput]=e.target.value});if(facilitatorMode&&!summaryMode){renderFacilitator=renderInstructor;render()}
let facilitatorUnlocked=sessionStorage.getItem('it235-facilitatorUnlocked')==='true';const baseInstructorRender=renderInstructor;renderInstructor=function(){if(!facilitatorUnlocked){document.body.classList.add('screen-mode');document.querySelector('.hero h1').textContent='Facilitator access';document.querySelector('.hero-copy').textContent='Enter the facilitator PIN to open the control room.';document.querySelector('.phase-nav').innerHTML='';content.innerHTML='<div class="facilitator-login"><div class="phase-kicker">Instructor control room</div><h2>Enter facilitator PIN</h2><p class="subhead">The dashboard is hidden until you authenticate in this browser session.</p><label for="facilitatorLoginPin">Facilitator PIN</label><input id="facilitatorLoginPin" type="password" inputmode="numeric" autocomplete="current-password" placeholder="PIN"><button class="primary-btn" data-auth-facilitator>Open control room</button><p class="helper">You will not be asked again until this browser session is cleared.</p></div>';return}baseInstructorRender();if(!document.querySelector('[data-reset-game]')){const b=document.createElement('button');b.className='danger-btn';b.dataset.resetGame='true';b.textContent='Clear and reset game';document.querySelector('.instructor-controls')?.appendChild(b)}};
document.addEventListener('click',e=>{if(e.target.closest('[data-auth-facilitator]')){const pin=String(document.querySelector('#facilitatorLoginPin')?.value||'').trim();if(!pin){showToast('Enter the facilitator PIN.');return}postResponse({action:'authenticate',pin}).then(r=>{if(!r.ok){showToast('Incorrect facilitator PIN.');return}facilitatorUnlocked=true;sessionStorage.setItem('it235-facilitatorUnlocked','true');sessionStorage.setItem('it235-facilitatorPin',pin);render()});return}if(e.target.closest('[data-reset-game]')){if(!confirm('Clear all teams, submissions, evidence requests, scores, and return to Phase 1?'))return;const pin=sessionStorage.getItem('it235-facilitatorPin')||'';postResponse({action:'resetGame',pin}).then(r=>{if(!r.ok){showToast('Reset failed. Re-enter the facilitator PIN.');facilitatorUnlocked=false;sessionStorage.removeItem('it235-facilitatorUnlocked');render();return}state.globalPhase=1;state.teams=[];state.requests=[];state.releasedEvidence=[];showToast('Game cleared. Ready for a clean start.');render()});return}});
if(summaryMode){const summaryBase=renderSummary;renderFacilitator=function(){if(!facilitatorUnlocked){renderInstructor();return}summaryBase()}}if(facilitatorMode)render();
let instructorPage=Number(sessionStorage.getItem('it235-instructorPage')||1);const pageNames=['Overview','Team review','Evidence queue','Score & advance'];function instructorNav(){return `<nav class="instructor-page-nav" aria-label="Instructor dashboard pages">${pageNames.map((x,i)=>`<button class="${instructorPage===i+1?'active':''}" data-inst-page="${i+1}"><span>0${i+1}</span>${x}</button>`).join('')}</nav>`}function instructorShell(body){return `<div class="instructor-head"><div><div class="phase-kicker">Instructor control room · ${pageNames[instructorPage-1]}</div><h2>${state.incident?.name||'Incident room'}</h2><p class="subhead">${instructorPage===1?'See the class position at a glance.':instructorPage===2?'Review team reasoning for the current phase and choose what to discuss.':instructorPage===3?'Review evidence requests and decide what to release.':'Score the process and advance everyone together.'}</p></div><a class="secondary-btn" href="?mode=facilitator&view=summary">Projector summary</a></div>${instructorNav()}${body}<div class="instructor-page-footer">${instructorPage>1?'<button class="secondary-btn" data-inst-page="'+(instructorPage-1)+'">← Previous</button>':'<span></span>'}${instructorPage<4?'<button class="primary-btn" data-inst-page="'+(instructorPage+1)+'">Next →</button>':'<span></span>'}</div>`}function renderInstructorPages(){const teams=state.teams.slice().sort((a,b)=>Number(b.ready)-Number(a.ready)||String(a.teamName).localeCompare(String(b.teamName)));const ready=teams.filter(t=>t.ready&&Number(t.phase)===state.globalPhase).length;const teamCards=teams.map(t=>{const answer=t.latest?.answer||{};const diagnosis=answer.issueDiagnosis||answer.developmentUpdate||answer.investigationDecision||'No current diagnosis submitted';const submitted=Boolean(t.ready&&Number(t.phase)===state.globalPhase);return `<article class="instructor-team ${submitted?'is-ready':''}"><div class="instructor-team-head"><div><span class="phase-kicker">${submitted?'Ready for review':t.ready?'Submitted earlier':'Working'}</span><h3>${t.teamName}</h3><small>${t.members}</small></div><div class="instructor-score"><strong>${t.score||0}</strong><span>pts</span></div></div><div class="instructor-status"><span class="status-pill">${submitted?'READY':'WAITING'}</span><span>Team phase ${t.phase||1}</span><span>${t.latest?.kind||'No submission'}</span></div><div class="instructor-diagnosis"><span>Discussion lead</span><p>${diagnosis}</p></div><div class="instructor-board"><span><b>Know</b>${t.board?.known||'—'}</span><span><b>Think</b>${t.board?.think||'—'}</span><span><b>Unknown</b>${t.board?.unknown||'—'}</span></div>${instructorPage===4?`<div class="score-entry"><input type="number" min="0" max="10" value="${instructorDrafts.scores[t.teamId]||''}" data-score-input="${t.teamId}" aria-label="Process points for ${t.teamName}" placeholder="0"><button class="primary-btn" data-score-team="${t.teamId}">Save points</button></div>`:''}</article>`}).join('');const requests=state.requests.map(r=>`<article class="request-row"><div><b>${r.teamName} · ${r.evidenceId}</b><p>${r.question||r.reason}</p><small>${r.reason}</small></div><button class="primary-btn" data-release-evidence="${r.evidenceId}">${r.status==='released'?'Released':'Release evidence'}</button></article>`).join('');let body='';if(instructorPage===1)body=`<section class="instructor-metrics"><div><span>Shared phase</span><strong>${state.globalPhase}</strong><small>${phases[state.globalPhase-1]}</small></div><div><span>Ready this phase</span><strong>${ready}/${teams.length}</strong><small>Teams submitted</small></div><div><span>Teams connected</span><strong>${teams.length}</strong><small>All registered teams</small></div><div><span>Stage timer</span><strong id="instructorTimer">${document.querySelector('#timerDisplay')?.textContent||'--:--'}</strong><small>Time remaining</small></div></section><section class="review-card instructor-controls"><h3>Class progress</h3><div class="screen-progress">${phases.map((x,i)=>`<span class="${i+1===state.globalPhase?'current':''} ${i+1<state.globalPhase?'done':''}"><i>${i+1}</i>${x}</span>`).join('')}</div><p>Use the pages above to review the current state, then advance when the class discussion is complete.</p></section>`;if(instructorPage===2)body=`<section class="review-card"><div class="instructor-controls-head"><div><span class="phase-kicker">Current phase · ${phases[state.globalPhase-1]}</span><h3>Team review · ${ready}/${teams.length} ready</h3></div></div><p>Use the diagnosis and board snapshots to choose which reasoning to bring into the class discussion.</p></section><section class="instructor-team-grid">${teamCards||'<div class="review-card summary-empty">Teams appear after registration.</div>'}</section>`;if(instructorPage===3)body=`<section class="review-card"><div class="instructor-controls-head"><div><span class="phase-kicker">Evidence queue</span><h3>Requests to discuss or release</h3></div><strong class="status-pill">${requests?state.requests.length:0} requests</strong></div>${requests||'<p class="summary-empty">No evidence requests yet.</p>'}</section>`;if(instructorPage===4)body=`<section class="review-card instructor-controls"><div class="instructor-controls-head"><div><span class="phase-kicker">Score &amp; advance</span><h3>Finish the discussion before releasing the next screen</h3></div><span class="status-pill">Phase ${state.globalPhase}</span></div><label for="facilitatorPin">Facilitator PIN</label><input id="facilitatorPin" type="password" value="${instructorDrafts.pin||sessionStorage.getItem('it235-facilitatorPin')||''}" placeholder="Enter facilitator PIN"><div class="console-buttons">${phases.map((x,i)=>`<button class="primary-btn ${i+1===state.globalPhase?'current-control':''} ${i+1===state.globalPhase+1?'next-control':''}" data-release-phase="${i+1}">${i+1===state.globalPhase?'Current: ':i+1===state.globalPhase+1?'Next: ':'Release '}${i+1} · ${x}</button>`).join('')}</div><button class="danger-btn" data-reset-game>Clear and reset game</button></section><section class="instructor-team-grid">${teamCards||'<div class="review-card summary-empty">Teams appear after registration.</div>'}</section>`;content.innerHTML=instructorShell(body);updateStageTimer();const timer=document.querySelector('#instructorTimer');if(timer)timer.textContent=document.querySelector('#timerDisplay')?.textContent||'--:--'}
if(facilitatorMode&&!summaryMode){renderInstructor=()=>{if(!facilitatorUnlocked){renderInstructorPages=()=>{};return}renderInstructorPages()};renderFacilitator=renderInstructor;render()}
document.addEventListener('click',e=>{const page=e.target.closest('[data-inst-page]');if(page&&facilitatorMode&&!summaryMode){instructorPage=Math.max(1,Math.min(4,Number(page.dataset.instPage)));sessionStorage.setItem('it235-instructorPage',String(instructorPage));render();return}},true);
function disableAutofill(){document.querySelectorAll('input,textarea').forEach((el,i)=>{el.autocomplete=el.type==='password'?'new-password':'off';el.name=el.name||`incident-field-${el.id||i}`;el.setAttribute('data-no-autofill','true')})}disableAutofill();new MutationObserver(disableAutofill).observe(document.body,{childList:true,subtree:true});
pageNames[2]='Submissions';const originalInstructorPages=renderInstructorPages;renderInstructorPages=function(){if(instructorPage!==3){originalInstructorPages();return}const submissions=state.teams.map(t=>{const latest=t.latest||{};const answer=latest.answer||{};const entries=Object.entries(answer).filter(([k,v])=>k!=='board'&&k!=='requestEvidence'&&String(v||'').trim()).map(([k,v])=>`<div class="submission-answer"><b>${k.replace(/[A-Z]/g,m=>' '+m).replace(/^./,m=>m.toUpperCase())}</b><p>${v}</p></div>`).join('');return `<article class="submission-card"><div class="instructor-team-head"><div><span class="phase-kicker">${latest.phase?`Phase ${latest.phase} · ${latest.kind||'Submission'}`:'No submission yet'}</span><h3>${t.teamName}</h3><small>${t.members}</small></div><div class="instructor-score"><strong>${t.score||0}</strong><span>pts</span></div></div>${latest.submittedAt?`<small class="submission-time">Submitted ${new Date(latest.submittedAt).toLocaleString()}</small>`:''}<div class="submission-answers">${entries||'<p class="summary-empty">This team has not submitted a response yet.</p>'}</div></article>`}).join('');content.innerHTML=instructorShell(`<section class="review-card"><div class="instructor-controls-head"><div><span class="phase-kicker">Team submissions</span><h3>Latest responses for class discussion</h3></div><strong class="status-pill">${state.teams.length} teams</strong></div><p>Use this page to compare what teams wrote, invite a team to explain its reasoning, and discuss how different evidence led to different conclusions.</p></section><section class="submission-grid">${submissions||'<div class="review-card summary-empty">No teams have registered yet.</div>'}</section>`);updateStageTimer()};if(facilitatorMode&&!summaryMode)render();
state.activityStarted=false;function instructorLobby(){const teams=state.teams.map(t=>`<article class="lobby-team"><div><span class="phase-kicker">Team connected</span><h3>${t.teamName}</h3><p>${t.members}</p></div><span class="status-pill">READY</span></article>`).join('');content.innerHTML=instructorShell(`<section class="lobby-hero"><div><div class="phase-kicker">Before the incident begins</div><h2>Get the class ready</h2><p class="subhead">Teams can enter their names and members now. The activity clock and student briefing will begin only when you start the activity.</p></div><div class="lobby-count"><strong>${state.teams.length}</strong><span>teams connected</span></div></section><section class="lobby-actions"><div><h3>${state.teams.length?'Teams are ready to go':'Waiting for teams to sign in'}</h3><p>${state.teams.length?'Confirm the team list, then start the shared activity.':'Leave this screen projected while teams register.'}</p></div><button class="primary-btn" data-start-activity ${state.teams.length?'':'disabled'}>Start activity</button></section><section class="lobby-team-grid">${teams||'<div class="summary-empty">No teams connected yet.</div>'}</section>`)}const pagedInstructorRender=renderInstructorPages;renderInstructorPages=function(){if(instructorPage===1&&!state.activityStarted){instructorLobby();return}pagedInstructorRender()};pageNames[0]='Get ready';
const normalStudentRender=render;render=function(){if(!facilitatorMode&&state.started&&!state.activityStarted){document.body.classList.add('screen-mode');document.querySelector('.hero h1').textContent='Waiting for the instructor';document.querySelector('.hero-copy').textContent='Your team is registered. The instructor will start the shared activity when everyone is ready.';document.querySelector('.phase-nav').innerHTML='';content.innerHTML='<div class="waiting-state"><div class="waiting-orbit"><i></i><i></i><i></i></div><div class="phase-kicker">Team registered</div><h2>Get ready</h2><p class="subhead">The briefing will open when the instructor starts the activity. Keep your team together and be ready to discuss.</p></div>';return}normalStudentRender()};document.addEventListener('click',e=>{if(e.target.closest('[data-start-activity]')){const pin=sessionStorage.getItem('it235-facilitatorPin')||'';postResponse({action:'startGame',pin}).then(r=>{if(!r.ok){showToast('Start failed. Sign in again.');return}state.activityStarted=true;state.globalPhase=1;showToast('Activity started.');render()})}});
setInterval(()=>{if(!state.activityStarted){const el=document.querySelector('#timerDisplay');if(el){el.textContent='08:00';el.classList.remove('urgent')}}},1000);
// Keep the facilitator entry point deterministic: the initial instructor screen
// is always the authenticated Get Ready lobby, never the legacy incident room.
if(facilitatorMode&&!summaryMode){
  renderFacilitator=function(){
    if(!facilitatorUnlocked){
      document.body.classList.add('screen-mode');
      document.querySelector('.hero h1').textContent='Facilitator access';
      document.querySelector('.hero-copy').textContent='Enter the facilitator PIN to open the control room.';
      document.querySelector('.phase-nav').innerHTML='';
      content.innerHTML='<div class="facilitator-login"><div class="phase-kicker">Instructor control room</div><h2>Enter facilitator PIN</h2><p class="subhead">The dashboard is hidden until you authenticate in this browser session.</p><label for="facilitatorLoginPin">Facilitator PIN</label><input id="facilitatorLoginPin" type="password" inputmode="numeric" autocomplete="new-password" placeholder="PIN"><button class="primary-btn" data-auth-facilitator>Open control room</button><p class="helper">You will not be asked again until this browser session is cleared.</p></div>';
      return;
    }
    renderInstructorPages();
  };
  render();
}

// Keep the pre-start lobby focused on team sign-in. Review, submissions, and
// scoring controls become available once the instructor starts the activity.
const fullInstructorShell=instructorShell;
instructorShell=function(body){
  const html=fullInstructorShell(body);
  if(instructorPage===1&&!state.activityStarted){
    return html.replace(/<nav class="instructor-page-nav"[\s\S]*?<\/nav>/,'').replace(/<div class="instructor-page-footer">[\s\S]*?<\/div>\s*$/,'');
  }
  return html;
};
if(facilitatorMode&&!summaryMode)render();

// Handle phase release before the legacy click listener so failures are visible
// and the student view advances only after the server confirms the change.
document.addEventListener('click',e=>{
  const release=e.target.closest('[data-release-phase]');
  if(!release||!facilitatorMode)return;
  e.preventDefault();
  e.stopImmediatePropagation();
  const nextPhase=Number(release.dataset.releasePhase);
  const pin=String(document.querySelector('#facilitatorPin')?.value||sessionStorage.getItem('it235-facilitatorPin')||'').trim();
  if(!pin){showToast('Enter the facilitator PIN before releasing a phase.');return}
  postResponse({action:'setPhase',phase:nextPhase,pin}).then(result=>{
    if(!result.ok){showToast(result.error||'The phase could not be released.');return}
    state.globalPhase=Number(result.currentPhase||nextPhase);
    showToast(`Released: ${phases[state.globalPhase-1]}`);
    setTimeout(sync,200);
  }).catch(()=>showToast('The server did not confirm the phase release.'));
},true);

// Manual classroom mode: every active team screen can move forward locally.
// This does not call the API, so advancing never reloads the page.
waitingScreen=function(){return `${progress(state.phase)}<div class="waiting-state"><div class="waiting-orbit"><i></i><i></i><i></i></div><div class="phase-kicker">Response saved · Screen ${String(state.phase).padStart(2,'0')}</div><h2>Pause and discuss</h2><p class="subhead">Compare your response with the class discussion. Revise it if needed, then use the manual advance button below when your team is ready for the next development.</p><div class="waiting-status"><span class="status-pill">READY TO CONTINUE</span><b>${phases[state.phase-1]}</b></div><button class="secondary-btn" data-edit-response>Edit current response</button>${scoringGuide()}</div>`};
function manualAdvance(){
  if(!state.started){showToast('Register your team before advancing.');return}
  if(state.phase>=7){showToast('This is the final stage.');return}
  saveFields();
  state.phase+=1;
  state.globalPhase=state.phase;
  state.waitingPhase=0;
  localStorage.removeItem('it235-waitingPhase');
  localStorage.removeItem('it235-testFloor');
  localStorage.removeItem('it235-phaseStartedAt');
  localStorage.setItem('it235-phase',String(state.phase));
  showToast(`Advanced to: ${phases[state.phase-1]}`);
  render();
}

// Bypass the retired pre-start instructor lobby and add the same control to
// every student-facing screen after the normal render completes.
const studentRender=normalStudentRender;
render=function(){
  studentRender();
  const old=document.querySelector('[data-manual-advance]');
  old?.closest('.manual-advance-row')?.remove();
  if(state.started){
    content.insertAdjacentHTML('beforeend',`<div class="manual-advance-row"><button class="primary-btn" data-manual-advance>${state.phase>=7?'Final stage':'Manual advance to next stage'}</button><span class="helper">Move the class forward when your team is ready.</span></div>`);
  }
};
document.addEventListener('click',e=>{
  const button=e.target.closest('[data-manual-advance]');
  if(!button)return;
  e.preventDefault();
  e.stopImmediatePropagation();
  manualAdvance();
},true);
// Disable the retired hidden-logo test control.
document.addEventListener('click',e=>{
  if(!e.target.closest('.waiting-orbit'))return;
  localStorage.removeItem('it235-testFloor');
  e.stopImmediatePropagation();
},true);
render();

// Individual-assignment presentation layer. Keep the existing storage/API
// field names for compatibility, but expose only individual-student language.
function startIndividualAssignment(){
  if(state.started){showToast('This assignment is already registered.');return}
  state.team=document.querySelector('#teamName').value.trim();
  if(!state.team){showToast('Enter your name before beginning.');return}
  state.members='Individual submission';
  state.teamId=crypto.randomUUID?crypto.randomUUID():String(Date.now());
  state.started=true;state.startedAt=Date.now();
  ['team','members','teamId','started','startedAt'].forEach(k=>localStorage.setItem('it235-'+k,state[k]));
  post({action:'registerTeam',teamId:state.teamId,teamName:state.team,members:state.members});
  showToast('Assignment started. The briefing is ready.');render();
}
startGame=startIndividualAssignment;
function individualizeUI(){
  state.members='Individual submission';
  localStorage.setItem('it235-members',state.members);
  const heroCopy=document.querySelector('.hero-copy');if(heroCopy&&heroCopy.textContent.includes('incident response team'))heroCopy.textContent='You are investigating a service incident. The information is incomplete, and your job is to ask better questions before making a change.';
  const nameLabel=document.querySelector('label[for="teamName"]');if(nameLabel)nameLabel.textContent='Your name';
  const nameInput=document.querySelector('#teamName');if(nameInput)nameInput.placeholder='Enter your name';
  const memberLabel=document.querySelector('label[for="teamMembers"]');const memberInput=document.querySelector('#teamMembers');
  if(memberLabel)memberLabel.style.display='none';if(memberInput)memberInput.style.display='none';
  const start=document.querySelector('#startBtn');if(start)start.textContent='Begin assignment';
  const saved=document.querySelector('#teamSaved');if(saved&&saved.textContent==='Team registered')saved.textContent='Assignment registered';
  const scoreSpans=document.querySelectorAll('.score-preview div:first-child span');if(scoreSpans[0])scoreSpans[0].textContent='Your score';
  const meta=document.querySelectorAll('.hero-meta span');if(meta[1])meta[1].textContent='◉ Individual assignment';
  const reportTeam=document.querySelector('[for="report-team"]');const reportMembers=document.querySelector('[for="report-members"]');
  if(reportTeam)reportTeam.textContent='Student name';if(reportMembers)reportMembers.textContent='Assignment type';
  const reportStatus=document.querySelector('.report-status');if(reportStatus)reportStatus.textContent='Ready to submit individually';
  document.querySelectorAll('#content *').forEach(el=>{if(el.children.length)return;const text=el.textContent;if(!text)return;el.textContent=text.replace(/your team/gi,'your response').replace(/the team’s/gi,'your').replace(/the team's/gi,'your').replace(/the team/gi,'you').replace(/team’s/gi,'your').replace(/team's/gi,'your').replace(/team note/gi,'individual note').replace(/team score/gi,'your score').replace(/team registered/gi,'assignment registered')});
}
const individualRender=render;
render=function(){individualRender();individualizeUI()};
render();

// Editable final submission form. Students can revise the generated report
// without returning through every dialogue screen, then export it as a PDF.
function reportInput(label,id,value){return `<div class="report-edit-field"><label for="report-${id}">${escapeHtml(label)}</label><textarea id="report-${id}" data-report-answer="${escapeHtml(id)}">${escapeHtml(value||'')}</textarea></div>`}
function editableReportHtml(){
  const board=Object.entries(dialogueReportLabels).map(([id,label])=>reportInput(label,id,id==='boardKnown'?state.board.known:id==='boardThink'?state.board.think:id==='boardUnknown'?state.board.unknown:state.board.ruledOut)).join('');
  const stages=Array.from({length:7},(_,i)=>{const p=i+1;const fields=(dialogueFields[p]||[]).map(([id,label])=>reportInput(label,id,state.answers[id])).join('');return `<section class="report-stage"><span class="phase-kicker">Stage ${String(p).padStart(2,'0')} · ${phases[i]}</span>${fields||'<p class="helper">No written response was required in this stage.</p>'}</section>`}).join('');
  return `<div class="completion-report"><div class="report-header"><div><div class="phase-kicker">Final submission form</div><h2>Review your team report</h2><p class="subhead">Make any final edits, save the report, then choose Export PDF for your Canvas submission.</p></div><div class="report-actions"><button class="primary-btn" data-save-report>Save edits</button><button class="primary-btn" data-export-pdf>Export PDF</button><button class="secondary-btn" data-copy-report>Copy report</button></div></div><div class="report-meta"><div><label for="report-team">Team</label><input id="report-team" data-report-meta="team" value="${escapeHtml(state.team)}"></div><div><label for="report-members">Members</label><input id="report-members" data-report-meta="members" value="${escapeHtml(state.members)}"></div><div><label>Status</label><span class="report-status">Ready to submit</span></div></div><section class="report-board"><h3>Incident board</h3><div class="report-board-grid">${board}</div></section>${stages}<p class="helper report-footer">PDF tip: in the print window, choose “Save as PDF” as the destination.</p></div>`;
}
function saveReportEdits(){
  document.querySelectorAll('[data-report-answer]').forEach(el=>{
    const id=el.dataset.reportAnswer;
    if(id==='boardKnown')state.board.known=el.value;
    else if(id==='boardThink')state.board.think=el.value;
    else if(id==='boardUnknown')state.board.unknown=el.value;
    else if(id==='boardRuledOut')state.board.ruledOut=el.value;
    else state.answers[id]=el.value;
  });
  const team=document.querySelector('[data-report-meta="team"]');
  const members=document.querySelector('[data-report-meta="members"]');
  if(team)state.team=team.value.trim();
  if(members)state.members=members.value.trim();
  localStorage.setItem('it235-team',state.team);localStorage.setItem('it235-members',state.members);
  localStorage.setItem('it235-answers',JSON.stringify(state.answers));localStorage.setItem('it235-board',JSON.stringify(state.board));
  if(state.teamId)post({action:'updateBoard',teamId:state.teamId,...state.board});
}
reportHtml=editableReportHtml;
document.addEventListener('input',e=>{
  if(!e.target.matches('[data-report-answer],[data-report-meta]'))return;
  const id=e.target.dataset.reportAnswer;
  if(id==='boardKnown')state.board.known=e.target.value;
  else if(id==='boardThink')state.board.think=e.target.value;
  else if(id==='boardUnknown')state.board.unknown=e.target.value;
  else if(id==='boardRuledOut')state.board.ruledOut=e.target.value;
  else if(id)state.answers[id]=e.target.value;
  if(e.target.dataset.reportMeta==='team')state.team=e.target.value;
  if(e.target.dataset.reportMeta==='members')state.members=e.target.value;
},true);
document.addEventListener('click',e=>{
  if(e.target.closest('[data-save-report]')){e.preventDefault();saveReportEdits();showToast('Report edits saved.');return}
  if(e.target.closest('[data-export-pdf]')){e.preventDefault();saveReportEdits();showToast('Choose “Save as PDF” in the print window.');window.print();return}
},true);
render();

// Final student-only dialogue flow. Each completed prompt advances directly
// to the next prompt; the final prompt becomes a portable grading report.
state.completed=localStorage.getItem('it235-completed')==='1';
state.evidenceStep=Number(localStorage.getItem('it235-evidenceStep')||0);
const evidenceCatalog=[
  {id:'user-interview',title:'User interview',type:'Phone call transcript',prompt:'Listen for the difference between what the user experienced and what they assumed.',content:'Caller: “The customer portal will not load from our office. Email is working, and I can reach the public status page. A coworker in another department is seeing the same portal problem.”'},
  {id:'service-desk',title:'Service desk tickets',type:'Grouped incident tickets',prompt:'Look for patterns across people, departments, locations, and unaffected services.',content:'08:47 Customer Service: portal timeout. 08:51 Finance: portal timeout. 08:54 Remote employee: portal timeout. One ticket says “the entire network is down,” but the reporter confirms email is working.'},
  {id:'monitoring',title:'Monitoring information',type:'Service dashboard snapshot',prompt:'Compare healthy signals with degraded signals instead of treating the whole environment as one system.',content:'Portal health check: GREEN from the monitoring location. Portal transaction latency: YELLOW and rising. Authentication: GREEN. Email: GREEN. Public status page: GREEN.'},
  {id:'recent-change',title:'Recent change record',type:'Change-management entry',prompt:'Use timing as a lead to test, not as proof that the change caused the incident.',content:'08:12 Routine certificate renewal completed. 08:31 Shared gateway configuration change completed. 08:36 Monitoring thresholds adjusted. 08:42 First customer report. The gateway change received a limited post-change check from one location.'},
  {id:'logs',title:'Application and gateway logs',type:'Log excerpt',prompt:'Find the repeated pattern, then decide what it supports and what it still does not prove.',content:'08:41:58 gateway route=portal upstream=dependency status=504 elapsed=30.02s\n08:42:11 gateway route=portal upstream=dependency status=504 elapsed=30.01s\n08:42:19 gateway route=portal upstream=dependency status=504 elapsed=30.03s\n08:42:22 gateway route=status-page status=200 elapsed=0.18s\n08:43:07 gateway route=portal upstream=dependency status=504 elapsed=30.02s\nPattern begins near the gateway configuration change; unaffected routes continue to return 200.'}
];
const dialogueFields={
  1:[['briefQuestions','First questions']],
  2:[['requestEvidence','Requested source'],['requestQuestion','Question behind the request'],['requestReason','Why this evidence matters'],['investigationDecision','Working hypothesis']],
  3:[['reviewSupport','Evidence supporting the hypothesis'],['reviewChange','Evidence that would change the team’s mind']],
  4:[['developmentUpdate','Updated thinking'],['nextAction','Next action'],['actionRisk','Risk and safeguard']],
  5:[['verificationChecks','Recovery checks'],['remainingRisk','Remaining risk'],['changeMindAgain','Result that would change the mind']],
  6:[['leadershipUpdate','Leadership update'],['confidence','Confidence and rationale']],
  7:[['afterAction','What the team did well'],['assumption','Assumption to challenge'],['prevention','Recommended improvement']]
};
dialogueFields[2]=evidenceCatalog.map(source=>[`evidenceNote-${source.id}`,`${source.title} — team note`]);
const dialogueReportLabels={boardKnown:'Known facts',boardThink:'Current thinking',boardUnknown:'Unknowns',boardRuledOut:'Ruled out'};
function reportValue(value){return String(value||'').trim()||'Not provided'}
function reportText(){
  const lines=[`IT235 INCIDENT COMMAND — INDIVIDUAL REPORT`,`Student: ${state.team}`,`Assignment: Individual incident response`,`Completed: ${new Date().toLocaleString()}`,``,'INCIDENT BOARD'];
  Object.entries(dialogueReportLabels).forEach(([id,label])=>lines.push(`${label}: ${reportValue(id==='boardKnown'?state.board.known:id==='boardThink'?state.board.think:id==='boardUnknown'?state.board.unknown:state.board.ruledOut)}`));
  for(let p=1;p<=7;p++){
    lines.push('',`STAGE ${p}: ${phases[p-1]}`);
    (dialogueFields[p]||[]).forEach(([id,label])=>lines.push(`${label}: ${reportValue(state.answers[id])}`));
  }
  return lines.join('\n');
}
function reportHtml(){
  const board=Object.entries(dialogueReportLabels).map(([id,label])=>`<div><b>${label}</b><p>${escapeHtml(reportValue(id==='boardKnown'?state.board.known:id==='boardThink'?state.board.think:id==='boardUnknown'?state.board.unknown:state.board.ruledOut))}</p></div>`).join('');
  const stages=Array.from({length:7},(_,i)=>{const p=i+1;const fields=(dialogueFields[p]||[]).map(([id,label])=>`<div><b>${escapeHtml(label)}</b><p>${escapeHtml(reportValue(state.answers[id]))}</p></div>`).join('');return `<section class="report-stage"><span class="phase-kicker">Stage ${String(p).padStart(2,'0')} · ${phases[i]}</span>${fields}</section>`}).join('');
  return `<div class="completion-report"><div class="report-header"><div><div class="phase-kicker">Simulation complete</div><h2>Team response report</h2><p class="subhead">Review this report with your team, then download or print it for submission.</p></div><div class="report-actions"><button class="primary-btn" data-download-report>Download report</button><button class="secondary-btn" data-print-report>Print report</button><button class="secondary-btn" data-copy-report>Copy report</button></div></div><div class="report-meta"><span><b>Team</b>${escapeHtml(state.team)}</span><span><b>Members</b>${escapeHtml(state.members)}</span><span><b>Status</b>Ready to submit</span></div><section class="report-board"><h3>Incident board</h3><div class="report-board-grid">${board}</div></section>${stages}<p class="helper report-footer">Submit the downloaded or printed report according to your instructor’s directions.</p></div>`;
}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderReport(){document.body.classList.add('screen-mode');content.innerHTML=reportHtml();content.classList.remove('screen-enter');requestAnimationFrame(()=>content.classList.add('screen-enter'))}
function evidenceScreen(){
  const source=evidenceCatalog[state.evidenceStep]||evidenceCatalog[0];
  const step=state.evidenceStep+1;
  return `${progress(2)}<div class="evidence-dialogue"><div class="phase-kicker">Evidence ${step} of ${evidenceCatalog.length} · ${source.type}</div><h2>${escapeHtml(source.title)}</h2><p class="subhead">${escapeHtml(source.prompt)}</p>${runningNotebook()}<article class="evidence-source"><div class="source-label">Source material</div><div class="evidence-content">${escapeHtml(source.content)}</div></article>${field(`evidenceNote-${source.id}`,'Add one note to the running incident notebook','What matters here? Capture the clue, your interpretation, or the next question it creates.')}${dialogueActionButtons('Save notebook note',state.evidenceStep===evidenceCatalog.length-1?'Continue to synthesis':'Next evidence source')}</div>`;
}
function runningNotebook(){
  const entries=evidenceCatalog.slice(0,state.evidenceStep).map(source=>`<article class="notebook-entry"><div><span class="notebook-source">${escapeHtml(source.title)}</span><span class="notebook-status">captured</span></div><p>${escapeHtml(reportValue(state.answers[`evidenceNote-${source.id}`]))}</p></article>`).join('');
  return `<section class="running-notebook"><div class="board-heading"><div><span class="phase-kicker">Running incident notebook</span><h3>Clues gathered so far</h3></div><span class="helper">${state.evidenceStep} of ${evidenceCatalog.length} sources reviewed</span></div>${entries||'<p class="notebook-empty">Your notes will collect here as the evidence arrives.</p>'}</section>`;
}
function dialogueActionButtons(label,nextLabel){return `<div class="dialogue-actions"><button class="secondary-btn" data-dialogue-back>← Back</button><button class="primary-btn" data-evidence-next>${nextLabel||label} →</button></div><div class="rubric-note"><b>Evidence response:</b> Your team is graded on what you noticed, how carefully you interpreted it, and whether your next question follows from the source.</div>`}
function validateEvidenceResponse(){
  const source=evidenceCatalog[state.evidenceStep];
  const ids=[`evidenceNote-${source.id}`];
  const missing=ids.filter(id=>!String(document.querySelector(`#${id}`)?.value||'').trim());
  document.querySelectorAll('.invalid').forEach(x=>x.classList.remove('invalid'));
  missing.forEach(id=>document.querySelector(`#${id}`)?.classList.add('invalid'));
  if(missing.length){showToast('Add a short note to the running notebook before continuing.');document.querySelector(`#${missing[0]}`)?.focus();return false}
  return true;
}
function backDialogue(){
  saveFields();
  if(state.phase===2&&state.evidenceStep>0){state.evidenceStep-=1;localStorage.setItem('it235-evidenceStep',String(state.evidenceStep));render();return}
  if(state.phase>1){state.phase-=1;state.globalPhase=state.phase;state.evidenceStep=state.phase===2?evidenceCatalog.length-1:0;localStorage.setItem('it235-phase',String(state.phase));localStorage.setItem('it235-evidenceStep',String(state.evidenceStep));render()}
}
screens[2]=evidenceScreen;
const priorDialogueRender=render;
render=function(){
  if(state.completed){renderReport();return}
  priorDialogueRender();
  document.querySelector('.manual-advance-row')?.remove();
  document.querySelector('.dialogue-toolbar')?.remove();
  if(state.started){content.insertAdjacentHTML('afterbegin',`<div class="dialogue-toolbar"><span class="helper">${state.phase===2?`Evidence source ${state.evidenceStep+1} of ${evidenceCatalog.length}`:`Stage ${state.phase} of ${phases.length}`}</span>${state.phase>1||state.evidenceStep>0?'<button class="secondary-btn" data-dialogue-back>← Back</button>':''}</div>`)}
};
submitPhase=function(){
  if(!state.started){showToast('Register your team first.');return}
  saveFields();
  if(!validateSubmission())return;
  const p=state.phase;
  const answers={...state.answers,board:state.board};
  post({action:'submit',teamId:state.teamId,teamName:state.team,phase:p,kind:phases[p-1],answer:JSON.stringify(answers),points:0});
  state.waitingPhase=0;
  localStorage.removeItem('it235-waitingPhase');
  if(p>=7){state.completed=true;localStorage.setItem('it235-completed','1');showToast('Dialogue complete. Your report is ready.');render();return}
  state.phase=p+1;state.globalPhase=state.phase;
  localStorage.setItem('it235-phase',String(state.phase));
  localStorage.removeItem('it235-phaseStartedAt');
  showToast(`Next dialogue: ${phases[state.phase-1]}`);
  render();
};
document.addEventListener('click',e=>{
  if(e.target.closest('[data-dialogue-back]')){e.preventDefault();e.stopImmediatePropagation();backDialogue();return}
  if(!e.target.closest('[data-evidence-next]'))return;
  e.preventDefault();e.stopImmediatePropagation();
  saveFields();
  if(!validateEvidenceResponse())return;
  if(state.evidenceStep<evidenceCatalog.length-1){state.evidenceStep+=1;localStorage.setItem('it235-evidenceStep',String(state.evidenceStep));showToast(`Next evidence source: ${evidenceCatalog[state.evidenceStep].title}`);render();return}
  state.phase=3;state.globalPhase=3;state.evidenceStep=0;
  localStorage.setItem('it235-phase','3');localStorage.setItem('it235-evidenceStep','0');
  showToast('Evidence review complete. Continue to synthesis.');render();
},true);
document.addEventListener('click',e=>{
  if(e.target.closest('[data-download-report]')){
    e.preventDefault();
    const blob=new Blob([reportText()],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`IT235-${state.team.replace(/[^a-z0-9]+/gi,'-')||'team'}-report.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);showToast('Report downloaded.');
  }
  if(e.target.closest('[data-print-report]')){e.preventDefault();window.print()}
  if(e.target.closest('[data-copy-report]')){e.preventDefault();navigator.clipboard?.writeText(reportText()).then(()=>showToast('Report copied to the clipboard.'))}
},true);
document.addEventListener('click',e=>{
  if(e.target.closest('#resetBtn')){localStorage.removeItem('it235-completed');localStorage.removeItem('it235-evidenceStep');}
},true);
render();
